INSERT INTO exercises (owner_id,name,type,kind,group_key,subtitle,primary_muscles,secondary_muscles,description,steps,rest_sec_default,created_at) VALUES (NULL,'Жим ногами, узкая постановка','weight_reps','legpress','legs','Квадрицепс · ягодицы','["quads"]','["glutes"]',NULL,'["Стопы узко внизу платформы.", "Опускай платформу, пока колени не у груди.", "Выжми без полного выпрямления коленей."]',150,1794476254915);
