INSERT INTO exercises (owner_id,name,type,kind,group_key,subtitle,primary_muscles,secondary_muscles,description,steps,rest_sec_default,created_at) VALUES (NULL,'Разгибания ног в тренажёре','weight_reps','legext','legs','Квадрицепс','["quads"]','[]',NULL,'["Валик на голени над стопой.", "Разогни ноги до конца и задержись.", "Медленно опусти."]',120,1794476254915);
INSERT INTO exercises (owner_id,name,type,kind,group_key,subtitle,primary_muscles,secondary_muscles,description,steps,rest_sec_default,created_at) VALUES (NULL,'Сгибания ног сидя','weight_reps','legcurl','legs','Бицепс бедра','["hamstrings"]','["calves"]',NULL,'["Валик над пятками, бёдра прижаты.", "Согни ноги до упора.", "Плавно верни."]',120,1794476254915);
INSERT INTO exercises (owner_id,name,type,kind,group_key,subtitle,primary_muscles,secondary_muscles,description,steps,rest_sec_default,created_at) VALUES (NULL,'Приседания со штангой','weight_reps','squat','legs','Квадрицепс · ягодицы','["quads", "glutes"]','["hamstrings", "lowerback"]',NULL,'["Гриф на трапециях, ноги на ширине плеч.", "Садись, отводя таз назад, колени по линии носков.", "Встань, толкаясь всей стопой."]',150,1794476254915);
INSERT INTO exercises (owner_id,name,type,kind,group_key,subtitle,primary_muscles,secondary_muscles,description,steps,rest_sec_default,created_at) VALUES (NULL,'Выпады с гантелями','weight_reps','lunge','legs','Квадрицепс · ягодицы','["quads", "glutes"]','["hamstrings"]',NULL,'["Гантели в опущенных руках.", "Шагни вперёд и опустись до касания коленом пола.", "Оттолкнись передней ногой и вернись."]',150,1794476254915);
