INSERT INTO exercises (owner_id,name,type,kind,group_key,subtitle,primary_muscles,secondary_muscles,description,steps,rest_sec_default,created_at) VALUES (NULL,'Тяга верхнего блока к груди','weight_reps','pulldown','back','Широчайшие · бицепс','["lats"]','["biceps", "reardelts"]',NULL,'["Хват шире плеч, бёдра под валиком.", "Тяни рукоять к верху груди, сводя лопатки.", "Медленно верни вверх."]',150,1794476254915);
